// SignInResult defines model for SignInResult.
type SignInResult struct {
	// Challenge code_sent only. Never contains or implies the code.
	Challenge *string `json:"challenge,omitempty"`

	// CsrfToken signed_in, BROWSER callers only (an Origin was sent): sent back as
	// X-CSRF-Token on every state-changing request of this session. Hold
	// it in memory only, never in storage, a cookie or a URL; after a
	// reload, GET /me returns it again.
	CsrfToken *string `json:"csrfToken,omitempty"`

	// DeviceToken Issued when a new device becomes trusted; NON-BROWSER callers only.
	// A browser's device is the __Secure-argon_device cookie.
	DeviceToken *string `json:"deviceToken,omitempty"`

	// ExpiresAt signed_in only. 8 hours for anyone holding a post, 30 days otherwise.
	ExpiresAt *time.Time `json:"expiresAt,omitempty"`

	// Message To show as written. code_not_sent: "We couldn't send your code just
	// now. Please try again in a minute. If it keeps failing, an officer of
	// your society can confirm this phone with you in person." code_sent
	// with a late code: "Your code may take a little longer to arrive. If
	// it hasn't come in a minute, try again." see_officer: why, for the
	// member.
	Message *string `json:"message,omitempty"`

	// Outcome signed_in: a session. code_sent: a code was handed to the SMS
	// provider (challenge given; when message is set, the provider gave no
	// readable answer and the code may be late). code_not_sent: the
	// provider refused it or could not be reached; NO challenge, try again
	// in a minute (the database's resend rule); the officer is named as
	// the fallback, never the first answer (2026-10-28). see_officer: no
	// single agreed number (a shared handset) or none: an officer confirms
	// the device in person.
	Outcome SignInResultOutcome `json:"outcome"`

	// Reason see_officer only: why. "ambiguous" — the credential matches more
	// than one person; "no_agreed_number" — no single registered number
	// to send a code to; "sms_unavailable" — TEMPORARY: codes cannot be
	// sent yet (no SMS provider), so a new device goes to an officer.
	Reason *string `json:"reason,omitempty"`

	// SessionToken signed_in, NON-BROWSER callers only (no Origin). A browser's
	// session is the __Host-argon_session cookie and is never in a body.
	SessionToken *string `json:"sessionToken,omitempty"`
}

// SignInResultOutcome signed_in: a session. code_sent: a code was handed to the SMS
// provider (challenge given; when message is set, the provider gave no
// readable answer and the code may be late). code_not_sent: the
// provider refused it or could not be reached; NO challenge, try again
// in a minute (the database's resend rule); the officer is named as
// the fallback, never the first answer (2026-10-28). see_officer: no
// single agreed number (a shared handset) or none: an officer confirms
// the device in person.
type SignInResultOutcome string

