// ServerInterface represents all server handlers.
type ServerInterface interface {
	// One approval request, in the caller's projection
	// (GET /approvals/{requestId})
	GetApproval(w http.ResponseWriter, r *http.Request, requestId openapi_types.UUID)
	// Authorise an approved withdrawal to execute (the hold), on the authoriser's own PIN step-up
	// (POST /approvals/{requestId}/holds)
	AuthorisePayout(w http.ResponseWriter, r *http.Request, requestId openapi_types.UUID)
	// Reject a request with one of the four reasons, resting on the rejecter's own PIN step-up
	// (POST /approvals/{requestId}/rejections)
	RejectApproval(w http.ResponseWriter, r *http.Request, requestId openapi_types.UUID)
	// Sign a request, resting on the signer's own PIN step-up
	// (POST /approvals/{requestId}/signatures)
	SignApproval(w http.ResponseWriter, r *http.Request, requestId openapi_types.UUID)
	// Complete a new-device sign-in with the code sent to the registered phone (public)
	// (POST /auth/codes/verify)
	PostVerifyCode(w http.ResponseWriter, r *http.Request)
	// The PIN step-up — a proof that authorises ONE act of ONE kind (0005)
	// (POST /auth/pin-proofs)
	PostPinProof(w http.ResponseWriter, r *http.Request)
	// Sign in with the one credential box and a PIN (public)
	// (POST /auth/sign-in)
	PostSignIn(w http.ResponseWriter, r *http.Request)
	// End this session
	// (POST /auth/sign-out)
	PostSignOut(w http.ResponseWriter, r *http.Request)
	// Liveness and database reachability
	// (GET /healthz)
	GetHealthz(w http.ResponseWriter, r *http.Request)
	// Release a hold whose transfer definitively failed, saying why
	// (POST /holds/{holdId}/releases)
	ReleaseHold(w http.ResponseWriter, r *http.Request, holdId openapi_types.UUID)
	// One loan's position as at a value date
	// (GET /loans/{loanId})
	GetLoan(w http.ResponseWriter, r *http.Request, loanId openapi_types.UUID, params GetLoanParams)
	// Who the caller is - their own member records and current posts
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// A member's loans as at a value date (the member, or an officer of their society)
	// (GET /members/{memberId}/loans)
	GetMemberLoans(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID, params GetMemberLoansParams)
	// A member's savings statement — one record, two projections
	// (GET /members/{memberId}/statement)
	GetMemberStatement(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID, params GetMemberStatementParams)
	// A member's savings, what they may withdraw now, and what was deducted and why
	// (GET /members/{memberId}/withdrawable)
	GetMemberWithdrawable(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID)
	// What a withdrawal of an amount would cost today (indicative)
	// (GET /members/{memberId}/withdrawal-quote)
	GetWithdrawalQuote(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID, params GetWithdrawalQuoteParams)
	// A member's own withdrawal requests, newest first, in the member projection
	// (GET /members/{memberId}/withdrawal-requests)
	GetMemberWithdrawalRequests(w http.ResponseWriter, r *http.Request, memberId openapi_types.UUID, params GetMemberWithdrawalRequestsParams)
	// The society's chart of accounts
	// (GET /societies/{societyId}/accounts)
	GetChartOfAccounts(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID)
	// One account's entries with a running balance
	// (GET /societies/{societyId}/accounts/{accountCode}/ledger)
	GetGeneralLedger(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, accountCode string, params GetGeneralLedgerParams)
	// The society's approval requests, newest first, in the officer projection
	// (GET /societies/{societyId}/approval-requests)
	GetSocietyApprovalRequests(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params GetSocietyApprovalRequestsParams)
	// Record a contribution that arrived, on the recorder's own PIN step-up
	// (POST /societies/{societyId}/contributions)
	RecordContribution(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params RecordContributionParams)
	// Entries with every line, filtered by reference, member, actor and value date
	// (GET /societies/{societyId}/journal)
	GetJournal(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params GetJournalParams)
	// postAll — commit a whole import in ONE transaction (LEDGER_CONTRACT §1)
	// (POST /societies/{societyId}/ledger/batches)
	PostLedgerBatch(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params PostLedgerBatchParams)
	// The society's loan book as at a value date (officers only)
	// (GET /societies/{societyId}/loans)
	GetSocietyLoans(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params GetSocietyLoansParams)
	// Record a payout that happened, on the recorder's own PIN step-up
	// (POST /societies/{societyId}/payouts)
	RecordPayout(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID)
	// Every account's debits, credits and balance as at a date
	// (GET /societies/{societyId}/trial-balance)
	GetTrialBalance(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params GetTrialBalanceParams)
	// Raise a withdrawal request, on the raiser's own PIN step-up
	// (POST /societies/{societyId}/withdrawal-requests)
	RaiseWithdrawalRequest(w http.ResponseWriter, r *http.Request, societyId openapi_types.UUID, params RaiseWithdrawalRequestParams)
}

